-- Approved standard thermal labels. Preserve IDs/default references, disabled state,
-- user edits, 58x40, planned/active shift layouts, inventory snapshots, duplicate jobs and A4 presets.
-- Only exact unedited former stock specs are replaced. Idempotent by old-spec guard.
-- Serialize the reference check with concurrent shift creation/activation.
DO $standard_labels$
BEGIN
PERFORM set_config('lock_timeout', '2s', true);
LOCK TABLE shifts IN SHARE MODE;
